import React from 'react';
import Col from 'react-bootstrap/esm/Col';
import Card from 'react-bootstrap/esm/Col';
import Image from 'react-bootstrap/esm/Image'
import {useHistory} from 'react-router-dom';
import {DISH_ROUTE} from '../utils/consts';
import {Context} from "../index";


const DishItem = ({dish}) => {

    const {eda} = useContext(Context)

    const history = useHistory()
    return (
        <Col md={3} className='mt-3' onClick={() => history.push(DISH_ROUTE + '/' + dish.id)}>
            <Card style={{width:150, cursor:'pointer'}} border={"light"}>
                <Image width={150} height={150} src={process.env.REACT_APP_API_URL + dish.img}/>
                {eda.types.map(type =>
                    <div className='mt-1' key={type.id}>{type.name}</div>
                )}
                <div>{dish.name}</div>
                <div>{dish.price} грн</div>
            </Card>
        </Col>
    );
};

export default DishItem;
